/* @autogenerated */
import { inject, Injectable, Injector, isDevMode, provideAppInitializer } from '@angular/core';
import {
  provideTranslocoMissingHandler,
  Translation,
  TRANSLOCO_CONFIG,
  TranslocoConfig,
  translocoConfig,
  TranslocoLoader,
  TranslocoService,
} from '@jsverse/transloco';
import { HttpClient } from '@angular/common/http';
import { Environment, environment } from 'app/bootstrap/environment/environment';
import { catchError, forkJoin, map, Observable, of, take } from 'rxjs';
import { rootLogger } from '@shared/context/observability/logger.service';
import { APP_CONFIG, RuntimeConfigService } from './app-config.service';
import { I18nConfig } from './app-config.model';
import { availableLanguages, defaultLanguage } from './defaults.service';
import { HumanizingMissingHandler } from './missing-handler';
import { MfeConfigAdapter } from './mfe-config.adapter';

@Injectable({ providedIn: 'root' })
export class I18nLoaderService implements TranslocoLoader {
  private http = inject(HttpClient);
  // Los idiomas se leen de la configuración actual: TRANSLOCO_CONFIG puede haberse creado antes de que llegue
  private config = inject(APP_CONFIG);
  private inj = inject(Injector);
  private mfe = inject(MfeConfigAdapter);
  /** Ficheros que ya han fallado: se avisa una sola vez por fichero. */
  private readonly warned = new Set<string>();

  getTranslation(path: string) {
    const pathParts = path.split('/');
    const lang = pathParts.pop() || '';
    const scope = pathParts.join('/');
    const conf = buildTranslocoConfig(this.config().i18n);
    // Dinamic append of language if is no available
    if (!(conf.availableLangs as string[]).includes(lang)) {
      const translocoService = this.inj.get(TranslocoService);
      translocoService.setAvailableLangs([...(conf.availableLangs as string[]), lang]);
    }
    // Merge upper languajes: un fichero ausente (p. ej. un scope sin en.json) no tumba el resto
    return forkJoin(langsPath(lang, conf).map((part) => this.fetch(this.url(scope, part)))).pipe(
      map((translations) => translations.reduce((acc, curr) => this.deepMerge(acc, curr), {})),
    );
  }

  private fetch(url: string): Observable<Translation> {
    return this.http.get<Translation>(url).pipe(
      take(1),
      catchError((err) => {
        if (!this.warned.has(url)) {
          this.warned.add(url);
          rootLogger.warn(`i18n: no se pudo cargar ${url}; se continúa sin él`, err?.status ?? err);
        }
        return of({});
      }),
    );
  }

  private url(scope: string, path: string) {
    // Los JSON de public/ no llevan hash: la versión evita servir traducciones de un despliegue anterior
    const target = (scope === '' ? '' : '/' + scope) + '/' + path + '.json' + versionQuery();
    return this.mfe.i18nBase(environment.name) + target;
  }

  private deepMerge(target: any, source: any): any {
    for (const key of Object.keys(source)) {
      if (typeof source[key] === 'object' && !Array.isArray(source[key]) && typeof target[key] === 'object') {
        // If both are objects: deepMerge again
        target[key] = this.deepMerge(target[key], source[key]);
      } else {
        // If is a primitive value: override
        target[key] = source[key];
      }
    }
    return target;
  }
}

/**
 * Configuración de Transloco a partir de `i18n` en la configuración en runtime.
 * TranslocoService puede crearse antes de que la configuración llegue (p. ej. desde otro APP_INITIALIZER):
 * arranca con los idiomas por defecto y se actualiza cuando llega.
 */
export function provideI18nConfiguration() {
  return [
    {
      provide: TRANSLOCO_CONFIG,
      useFactory: () => buildTranslocoConfig(inject(APP_CONFIG)().i18n),
    },
    provideTranslocoMissingHandler(HumanizingMissingHandler),
    provideAppInitializer(() => {
      const transloco = inject(TranslocoService);
      inject(RuntimeConfigService).config$.subscribe((config) => {
        transloco.setAvailableLangs(availableLanguages(config.i18n));
        transloco.setDefaultLang(defaultLanguage(config.i18n));
      });
    }),
  ];
}

function buildTranslocoConfig(conf: I18nConfig | undefined): TranslocoConfig {
  return translocoConfig({
    availableLangs: availableLanguages(conf),
    defaultLang: defaultLanguage(conf),
    reRenderOnLangChange: true,
    prodMode: !isDevMode(),
  });
}

/** Solo en builds (`buildDate` presente): en `ng serve` y en tests las URLs quedan limpias. */
export function versionQuery(env: Environment = environment): string {
  return env.buildDate ? '?v=' + encodeURIComponent(env.version) : '';
}

/**
 * Ficheros a fusionar, del más general al más específico: idioma por defecto, idioma base y variante regional
 * (`es-ES` → `en`, `es`, `es-ES`). Al fusionarse en este orden, el más específico pisa al resto.
 */
function langsPath(failedLang: string, config: TranslocoConfig): string[] {
  const lang = failedLang.split('/').pop() || '';
  const baseLang = lang.split('-');
  const paths: string[] = [config.defaultLang];
  let preffix = '';
  baseLang.forEach((part) => {
    preffix += (preffix.length == 0 ? '' : '-') + part;
    if (!paths.includes(preffix) && (config.availableLangs as string[]).includes(preffix)) {
      paths.push(preffix);
    }
  });
  return paths;
}
